class Solution {
    public long maximumSum(List<Integer> nums){
        int n=nums.size();
        boolean[] squareFree=new boolean[n+1];
        Arrays.fill(squareFree,true);
        for(int factor=2;factor*factor<=n;factor++){
            int square=factor*factor;
            for(int multiple=square;multiple<=n;multiple+=square)squareFree[multiple]=false;
        }
        long answer=0;
        for(int base=1;base<=n;base++){
            if(!squareFree[base])continue;
            long sum=0;
            for(int multiplier=1;(long)base*multiplier*multiplier<=n;multiplier++)sum+=nums.get(base*multiplier*multiplier-1);
            answer=Math.max(answer,sum);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun maximumSum(nums:List<Int>):Long{
        val n=nums.size;
        val squareFree=BooleanArray(n+1){
            true
        };
        var factor=2;
        while(factor*factor<=n){
            val square=factor*factor;
            var multiple=square;
            while(multiple<=n){
                squareFree[multiple]=false;
                multiple+=square
            };
            factor++
        };
        var answer=0L;
        for(base in 1..n){
            if(!squareFree[base])continue;
            var sum=0L;
            var multiplier=1;
            while(base.toLong()*multiplier*multiplier<=n){
                sum+=nums[base*multiplier*multiplier-1];
                multiplier++
            };
            answer=maxOf(answer,sum)
        };
        return answer
    }
}

